// Some portions generated by Claude

// Plan task M14.3 (user request): settings panes open over the page. An open pane is placed below its toggle, its
// end at the toggle's end, kept inside its card; a press outside it or Escape in it closes it.
const test = require('node:test');
const assert = require('node:assert/strict');

const { createScriptHarness } = require('./script-harness.js');

/** A key press as the document sees it. */
const key = (name, handled) => ({ key: name, defaultPrevented: !!handled,
    preventDefault() { this.defaultPrevented = true; } });

const rect = (left, top, width, height) => ({ left, top, width, height, right: left + width, bottom: top + height,
    x: left, y: top });

/**
 * A card from x 100 to 900 (1 px border, 20 px padding: content from 121 to 879) at y 40, holding a pane whose
 * toggle spans x 700 to 820 and y 100 to 136; the card is the box the panel is positioned in.
 */
function paneHarness(options = {}) {
    const harness = createScriptHarness({ window: options.window });
    harness.document.documentElement = { clientWidth: options.viewport || 1000 };
    harness.runScript('tools/workbench/src/main/webapp/scripts/template.js');
    const element = (tagName, elementOptions, parent) => {
        const created = harness.registerElement(tagName, elementOptions || {});
        (parent || harness.document.body).appendChild(created);
        return created;
    };
    const card = element('section', { className: options.cardClass || 'workbench-island', style: {
        borderLeftWidth: '1px', borderRightWidth: '1px', paddingLeft: '20px', paddingRight: '20px' } });
    card.getBoundingClientRect = () => rect(100, 40, 800, 400);
    Object.assign(card, { clientLeft: 1, clientTop: 1, scrollLeft: 0, scrollTop: 0 });
    const owner = element('div', { className: 'workbench-disclosure' }, card);
    const button = element('button', { id: 'pane-toggle',
        attributes: { 'aria-controls': 'pane-panel', 'aria-expanded': 'false' } }, owner);
    let buttonBox = options.button || rect(700, 100, 120, 36);
    button.getBoundingClientRect = () => buttonBox;
    const panel = element('div', { id: 'pane-panel', className: 'workbench-disclosure__panel', hidden: true }, owner);
    panel.getBoundingClientRect = () => rect(0, 0, options.panelWidth || 300, 120);
    panel.offsetParent = card;
    const field = element('input', { id: 'pane-field' }, panel);
    const outside = element('button', { id: 'elsewhere' });
    const release = harness.workbench.detailDisclosure.bind(button, panel, owner);
    return {
        harness, workbench: harness.workbench, document: harness.document, card, owner, button, panel, field, outside,
        release,
        moveButton(box) { buttonBox = box; },
        position: (name) => panel.style.getPropertyValue('--workbench-disclosure-' + name),
        open: () => button.getAttribute('aria-expanded') === 'true' && !panel.hidden
    };
}

test('an open pane is placed below its toggle with its end at the toggle\'s end', () => {
    const pane = paneHarness();

    pane.button.click();

    assert.equal(pane.open(), true);
    assert.equal(pane.position('left'), '419px', 'x 520 (820 - 300) in the card\'s padding box at 101');
    assert.equal(pane.position('top'), '95px', 'the toggle\'s bottom, 136, in the padding box at 41');
    assert.equal(pane.position('max-width'), '758px', 'never wider than the card\'s content');
    assert.equal(pane.position('anchor-x'), '240px', 'the arrow points at the toggle\'s center, 760');
});

test('a pane in a toolbar opens below the whole toolbar, so it covers none of the toolbar\'s buttons', () => {
    const pane = paneHarness();
    pane.owner.className = 'workbench-disclosure workbench-action-toolbar';
    pane.owner.getBoundingClientRect = () => rect(120, 90, 760, 100);

    pane.button.click();

    assert.equal(pane.position('top'), '149px', 'the toolbar\'s bottom, 190, in the padding box at 41');
});

test('a pane moves inward to stay inside its card and the viewport', () => {
    const left = paneHarness({ button: rect(130, 100, 120, 36), panelWidth: 500 });
    left.button.click();
    assert.equal(left.position('left'), '20px', 'it starts at the card\'s content edge, 121');
    assert.equal(left.position('anchor-x'), '69px');

    const narrow = paneHarness({ viewport: 700 });
    narrow.button.click();
    assert.equal(narrow.position('left'), '291px', 'it ends 8 px inside a viewport narrower than the card (692 - 300)');
    assert.equal(narrow.position('max-width'), '571px');
    assert.equal(narrow.position('anchor-x'), '296px', 'the arrow stays 4 px inside the pane');

    const unbounded = paneHarness({ cardClass: 'plain-box' });
    unbounded.button.click();
    assert.equal(unbounded.position('left'), '419px', 'outside a card the viewport is the limit');
    assert.equal(unbounded.position('max-width'), '984px');
});

test('a pane stays inside an element that clips what overflows it sideways', () => {
    const pane = paneHarness();
    Object.assign(pane.owner.style, { overflowX: 'clip', borderLeftWidth: '0px', borderRightWidth: '0px' });
    pane.owner.getBoundingClientRect = () => rect(150, 90, 610, 60);

    pane.button.click();

    assert.equal(pane.position('left'), '359px', 'it ends at the clipping edge, 760');
    assert.equal(pane.position('max-width'), '610px');
});

test('a right-to-left pane starts at its toggle\'s left edge', () => {
    const pane = paneHarness({ button: rect(300, 100, 120, 36) });
    pane.panel.style.direction = 'rtl';

    pane.button.click();

    assert.equal(pane.position('left'), '199px');
    assert.equal(pane.position('anchor-x'), '60px');
});

test('a pane follows its toggle when the page is resized', () => {
    const pane = paneHarness();
    pane.button.click();

    pane.moveButton(rect(600, 200, 120, 36));
    pane.harness.window.trigger('resize');

    assert.equal(pane.position('left'), '319px');
    assert.equal(pane.position('top'), '195px');
});

test('a pane that has no box to be positioned in is left where the stylesheet puts it', () => {
    const pane = paneHarness();
    pane.panel.offsetParent = null;

    pane.button.click();

    assert.equal(pane.open(), true);
    assert.equal(pane.position('left'), '');
});

test('a press outside an open pane closes it; a press in it or on its toggle does not', () => {
    const pane = paneHarness();
    assert.equal(pane.document.listenerCount('pointerdown'), 0, 'nothing listens while every pane is closed');
    pane.button.click();
    assert.equal(pane.document.listenerCount('pointerdown'), 1);

    pane.document.trigger('pointerdown', { target: pane.field });
    assert.equal(pane.open(), true, 'a press in the pane');
    pane.document.trigger('pointerdown', { target: pane.button });
    assert.equal(pane.open(), true, 'a press on its toggle, whose click closes it');
    pane.document.trigger('pointerdown', { target: pane.outside });

    assert.equal(pane.open(), false);
    assert.equal(pane.document.listenerCount('pointerdown'), 0, 'the listeners go with the last open pane');
    assert.equal(pane.document.listenerCount('keydown'), 0);
});

test('Escape in an open pane or on its toggle closes it and returns focus to the toggle', () => {
    const pane = paneHarness();
    pane.button.click();

    pane.outside.focus();
    const elsewhere = pane.document.trigger('keydown', key('Escape'));
    assert.equal(pane.open(), true, 'Escape outside the pane belongs to the page');
    assert.equal(elsewhere.defaultPrevented, false);
    pane.field.focus();
    pane.document.trigger('keydown', key('Enter'));
    pane.document.trigger('keydown', key('Escape', true));
    assert.equal(pane.open(), true, 'another key, or an Escape already handled');

    const escape = pane.document.trigger('keydown', key('Escape'));

    assert.equal(pane.open(), false);
    assert.equal(escape.defaultPrevented, true, 'a full-screen result does not also close');
    assert.equal(pane.document.activeElement, pane.button);

    pane.button.click();
    pane.button.focus();
    pane.document.trigger('keydown', key('Escape'));
    assert.equal(pane.open(), false, 'Escape on the toggle');
});

test('Escape closes a pane opened with a click that left focus on an element around its toggle', () => {
    // Safari does not focus a button that is clicked: focus stays on the page or the outlet around the toggle.
    const pane = paneHarness();
    pane.button.click();
    pane.card.focus();

    const escape = pane.document.trigger('keydown', key('Escape'));

    assert.equal(pane.open(), false);
    assert.equal(escape.defaultPrevented, true);
    assert.equal(pane.document.activeElement, pane.button);
});

test('a click on the toggle that closes a pane holding focus gives focus to the toggle in Safari too', () => {
    // Safari does not focus a button that is clicked: the press moves focus from the pane to the page or the outlet
    // around the toggle before the click, so the toggle cannot see that focus was in the pane when its click closes it.
    const pane = paneHarness();
    pane.button.click();
    pane.field.focus();

    pane.document.trigger('pointerdown', { target: pane.button });
    pane.card.focus();
    pane.button.trigger('click');

    assert.equal(pane.open(), false);
    assert.equal(pane.document.activeElement, pane.button);

    pane.button.click();
    pane.outside.focus();
    pane.document.trigger('pointerdown', { target: pane.button });
    pane.card.focus();
    pane.button.trigger('click');

    assert.equal(pane.open(), false);
    assert.equal(pane.document.activeElement, pane.card, 'focus that was not in the pane stays where Safari left it');
});

test('releasing an open pane stops listening and stops watching its card', () => {
    const observed = new Set();
    class ResizeObserver {
        observe(element) { observed.add(element); }
        unobserve(element) { observed.delete(element); }
        disconnect() { observed.clear(); }
    }
    const pane = paneHarness({ window: { ResizeObserver } });
    pane.button.click();
    assert.equal(observed.has(pane.card), true, 'its card is watched, so a card that grows moves the pane');
    assert.equal(observed.has(pane.button), true);

    pane.release();

    assert.equal(observed.size, 0);
    assert.equal(pane.document.listenerCount('pointerdown'), 0);
    assert.equal(pane.document.listenerCount('keydown'), 0);
});

test('releasing a pane keeps its target watched while another pane uses it as content', () => {
    const observed = new Set();
    class ResizeObserver {
        observe(element) { observed.add(element); }
        unobserve(element) { observed.delete(element); }
        disconnect() { observed.clear(); }
    }
    const pane = paneHarness({ window: { ResizeObserver } });
    assert.equal(observed.has(pane.field), true, 'the outer pane watches its direct content');

    const releaseInner = pane.workbench.detailDisclosure.bind(pane.outside, pane.field, pane.card);
    assert.equal(observed.has(pane.field), true, 'the inner pane also watches the shared target');

    releaseInner();

    assert.equal(observed.has(pane.field), true, 'the outer pane still uses the target as content');
    pane.release();
    assert.equal(observed.has(pane.field), false, 'the target is released with its final owner');
});
